      "rationale": "These spans supply consistent measurement, repeated observations, readiness classification, the calendar discrepancy and the limits on inference."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C033.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
